"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[647],{6490:e=>{e.exports=JSON.parse('{"functions":[{"name":"replicator","desc":"Creates a [SavedReplicator] for the part of the saved data that `lookup` returns. The saved data passed to\\n`lookup` is fully typed from the source\'s GreenTea type.\\n\\n```lua\\nresearchReplicator = PlayerDataSource:replicator(gt.array(gt.string()), function(playerData)\\n\\treturn playerData.research\\nend),\\n```\\n\\n`lookup` must return an existing table from the saved data, or a primitive, and must not yield. Changes are\\nfound by comparing what it returns, so a lookup that builds a new table counts as changed on every save.","params":[{"name":"valueType","desc":"","lua_type":"GreenTeaType"},{"name":"lookup","desc":"","lua_type":"(savedData: D) -> T"},{"name":"incrementalConfig","desc":"","lua_type":"SavedIncrementalConfig<T, P>?"}],"returns":[{"desc":"","lua_type":"SavedReplicator<D, T, P>"}],"function_type":"method","source":{"line":152,"path":"src/Replication/Kinds/SavedReplicator/SavedSource.luau"}},{"name":"setFetchFunction","desc":"Sets the function that returns a player\'s saved data, yielding until it has loaded, or `nil` if it never loads.\\nReplicators from this source wait for it to be set.\\n\\n```lua\\nPlayerDataSource:setFetchFunction(function(player)\\n\\tlocal didLoad, playerData = PlayerDataServer.waitForPlayerData(player)\\n\\treturn if didLoad then playerData else nil\\nend)\\n```","params":[{"name":"fetchAsync","desc":"","lua_type":"(player: Player) -> D?"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":196,"path":"src/Replication/Kinds/SavedReplicator/SavedSource.luau"}},{"name":"replicateChanges","desc":"Tells the source that a player\'s saved data changed, including when it first loads (`oldData` is `nil`). Each\\nreplicator whose part changed sends it to the player, then fires its `onChanged`. Call this from your store\'s\\nchange callback.\\n\\n```lua\\nPlayerDataSource:replicateChanges(player, newData, oldData)\\n```","params":[{"name":"player","desc":"","lua_type":"Player"},{"name":"newData","desc":"","lua_type":"D"},{"name":"oldData","desc":"","lua_type":"D?"}],"returns":[],"function_type":"method","realm":["Server"],"source":{"line":218,"path":"src/Replication/Kinds/SavedReplicator/SavedSource.luau"}}],"properties":[],"types":[],"name":"SavedSource","desc":"One store of saved player data, such as a DataStore wrapper, created with [Sencha.savedSource]. Saved\\nreplicators are created from it, and the server connects it to the store with\\n[SavedSource:setFetchFunction] and [SavedSource:replicateChanges].\\n\\nSencha doesn\'t depend on any data store library. A game with two stores creates two sources, and they never\\ninterfere.\\n\\nIn Studio, the source\'s GreenTea type also checks the data it receives, and errors once if it doesn\'t match.","source":{"line":65,"path":"src/Replication/Kinds/SavedReplicator/SavedSource.luau"}}')}}]);